int isPermutation(const char *a, const char *b) {
    size_t lenA = strlen(a), lenB = strlen(b);
    if (lenA != lenB) return 0;
    char *bArray = strdup(b);
    int found = 0;
    for (size_t i = 0; i < lenA; i++) {
        for (size_t k = 0; k < lenB; k++) {
            if (a[i] == bArray[k]) {
                found++;
                bArray[k] = (char)0xFF;
                break;
            }
        }
    }
    free(bArray);
    return found == (int)lenA;
}

