public int solution (int X, int [] A) {
    Set < Integer > seen = new HashSet < Integer > ();
    int sum = 0;
    int targetSum = X * (X + 1) / 2;
    for (int i = 0;
    i < A.length; i ++) {
        int value = A [i];
        if (value <= X && seen.add (value)) {
            sum += value;
            if (sum == targetSum) {
                return i;
            }
        }
    }
    return - 1;
}

